    vector<ull> G(n+1,1);
    for(int r=1;r<=n;r++){
        ull ar=a[r]; ull cur=1;
        for(int l=r-1;l>=1;l--){
            ull c=igcd(ar,a[l]);
            if(cur%c!=0){ ull g=igcd(cur,c); cur=(cur/g)*c; }
            G[l]=cur;
        }
        for(int l=1;l<=r-1;l++){
            ull f=ar/G[l];
            if(f!=1) dp[l]=dp[l]*(ll)(f%(ull)MOD)%MOD;
