#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
typedef long long ll;
static const ll MOD = 1000000007LL;
static inline ull igcd(ull a, ull b){ while(b){ ull t=a%b; a=b; b=t;} return a; }
static inline ull bingcd(ull a, ull b){
    if(!a) return b; if(!b) return a;
    int s=__builtin_ctzll(a|b);
    a>>=__builtin_ctzll(a);
    do{ b>>=__builtin_ctzll(b); if(a>b) swap(a,b); b-=a; }while(b);
    return a<<s;
}
static ull a[305],G[305];
static ll dp[305];
template<class F>
double bench(F gcd, bool fib){
    mt19937_64 rng(4242);
    int T=300,n=300; ull MASK=((ull)1<<60)-1;
    vector<ull> fibs={1,1};
    while(true){ ull nxt=fibs[fibs.size()-1]+fibs[fibs.size()-2]; if(nxt>(1ULL<<60)) break; fibs.push_back(nxt); }
    ull F1=fibs[fibs.size()-1], F2=fibs[fibs.size()-2];
    auto t0=chrono::high_resolution_clock::now();
    for(int tc=0;tc<T;tc++){
        for(int i=1;i<=n;i++){ if(fib) a[i]=(i&1)?F2:F1; else {ull v=rng()&MASK; a[i]=v?v:1;} }
        for(int r=1;r<=n;r++){
            ull ar=a[r],cur=1; ll arm=(ll)(ar%MOD);
            for(int l=r-1;l>=1;l--){
                ull c=gcd(ar,a[l]);
                if(c!=1 && cur%c!=0){ ull g=gcd(cur,c); cur=(cur/g)*c; }
                G[l]=cur;
            }
            for(int l=1;l<=r-1;l++){ ull gl=G[l]; if(gl==1) dp[l]=dp[l]*arm%MOD; else if(gl!=ar){ ull f=ar/gl; dp[l]=dp[l]*(ll)(f%(ull)MOD)%MOD; } }
            dp[r]=arm;
        }
    }
    auto t1=chrono::high_resolution_clock::now();
    return chrono::duration<double,milli>(t1-t0).count();
}
int main(){
    printf("euclid random: %.1f\n", bench(igcd,false));
    printf("bingcd random: %.1f\n", bench(bingcd,false));
    printf("euclid fib   : %.1f\n", bench(igcd,true));
    printf("bingcd fib   : %.1f\n", bench(bingcd,true));
    return 0;
}

